// A Menger sponge: a cube with a cross cut through it, then the same cut in each of the
// 20 smaller cubes left over, and so on. It is ray marched, and a plane slices it open to
// show the inside. On the [Timeline], iFloat0 is the number of levels, iFloat1 moves the
// slicing plane, iFloat2 and iFloat3 turn and tilt the camera, and iFloat4 swings the light.
// Each has a slider in the [Sliders] tab.
#define levels iFloat0
#define cutPosition iFloat1
#define cameraTurn iFloat2
#define cameraTilt iFloat3
#define lightSwing iFloat4
#define MAX_STEPS 256
#define HIT_THRESHOLD 0.00001
#define FLOOR_COLOR vec3(1.0)
#define SPONGE_COLOR vec3(0.970, 0.647, 0.151)
// The slicing plane faces along the cube's diagonal. cutPosition is its distance from the
// middle of the cube's base, where the floor's origin is.
#define CUT_NORMAL vec3(0.57735)

// A 2D rotation, used to turn a pair of coordinates such as xz.
mat2 rotate(float angle) {
  float c = cos(angle);
  float s = sin(angle);
  return mat2(c, s, -s, c);
}

// The distance from p to a cube of side 6 with a cross of square bars, 2 wide, cut out
// through it along all three axes: one level of the sponge.
float crossedCube(vec3 p) {
  vec3 a = abs(p);
  float maxYZ = max(a.y, a.z);
  float maxXZ = max(a.x, a.z);
  float maxXY = max(a.x, a.y);
  // For each bar, the distance to its side is the larger of the other two coordinates.
  // The bar along the axis where p is largest is the one that matters.
  float bars = 1.0 - (step(maxYZ, a.x) * maxYZ + step(maxXZ, a.y) * maxXZ + step(maxXY, a.z) * maxXY);
  float cube = max(maxXY, a.z) - 3.0;
  return max(bars, cube);
}

// The sponge: repeat the crossed cube at a third of the size each level, tiled so each
// smaller cube gets its own copy.
float sponge(vec3 p) {
  float scale = 1.0;
  float dist = 0.0;
  for (int i = 0; i < int(levels); i++) {
    dist = max(dist, crossedCube(p) * scale);
    p = fract((p - 1.0) * 0.5) * 6.0 - 3.0;
    scale /= 3.0;
  }
  return dist;
}

// The distance to the nearest surface (in .x) and its colour (in .yzw): a white floor, and
// the sponge sitting on it with everything beyond the slicing plane cut away.
vec4 scene(vec3 p) {
  float floorDist = p.y;
  float spongeDist = max(sponge(p - vec3(0.0, 3.0, 0.0)), dot(p, CUT_NORMAL) - cutPosition);
  return floorDist < spongeDist ? vec4(floorDist, FLOOR_COLOR) : vec4(spongeDist, SPONGE_COLOR);
}

// The surface normal, from how the distance changes when p moves a little along each axis.
vec3 sceneNormal(vec3 p, float d) {
  float eps = 0.001;
  return normalize(vec3(
    scene(p + vec3(eps, 0.0, 0.0)).x - d,
    scene(p + vec3(0.0, eps, 0.0)).x - d,
    scene(p + vec3(0.0, 0.0, eps)).x - d
  ));
}

// 0.2 if something blocks the way from p to the light, 1.0 if not.
float shadow(vec3 p, vec3 toLight, float maxDist) {
  float t = 0.01;
  for (int i = 0; i < 128; i++) {
    float h = scene(p + toLight * t).x;
    if (h < 0.0001 && i > 0) {
      return 0.2;
    }
    t += h;
    if (t > maxDist) {
      break;
    }
  }
  return 1.0;
}

// Diffuse lighting from a light at light.xyz that reaches light.w away.
vec3 shade(vec3 p, vec3 normal, vec3 color, vec4 light) {
  vec3 toLight = light.xyz - p;
  float lightDist = length(toLight);
  toLight /= lightDist;

  float diffuse = 1.5 * max(0.0, dot(normal, toLight));
  float falloff = 1.0 - pow(min(1.0, lightDist / light.w), 2.0);
  float brightness = 0.1 + diffuse * falloff * shadow(p, toLight, lightDist);

  // Paint the freshly cut face white.
  color = mix(color, vec3(1.0), 1.0 - smoothstep(0.0, 0.001, abs(dot(p, CUT_NORMAL) - cutPosition)));
  return brightness * color;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  // The camera looks down at the sponge, turning around it and tilting.
  vec2 ndc = 2.0 * fragCoord / iResolution - 1.0;
  vec2 xy = 0.32 * ndc * vec2(iResolution.x / iResolution.y, 1.0);
  vec3 dir = normalize(vec3(xy, -1.0));
  dir.zy = rotate(cameraTilt) * dir.zy;
  dir.xz = rotate(cameraTurn) * dir.xz;
  vec3 camera = vec3(0.0, 12.2, 14.0);
  camera.xz = rotate(cameraTurn) * camera.xz;

  // Two lights: one up to the side that swings round, and one at the camera.
  vec4 light = vec4(12.0, 9.2, 9.0, 30.0);
  light.xz = rotate(-1.5707963 * lightSwing) * light.xz;
  vec4 cameraLight = vec4(camera - vec3(0.01, 0.01, 0.0), 20.0);

  // March along the ray, stepping by the distance to the nearest surface each time.
  vec3 p = camera;
  vec3 col = vec3(0.0);
  for (int i = 0; i < MAX_STEPS; i++) {
    vec4 s = scene(p);
    if (s.x < HIT_THRESHOLD) {
      vec3 normal = sceneNormal(p, s.x);
      col = 0.5 * shade(p, normal, s.yzw, light) + 0.5 * shade(p, normal, s.yzw, cameraLight);
      break;
    }
    p += s.x * dir;
  }
  fragColor = vec4(col, 1.0);
}
